/**
 * The 2026-08-28 Greenhouse run: the same question answered with a positive
 * for a profile with no work country on file, and with no posting passed at
 * all. Both were the empty-`workCountries` short-circuit claiming
 * authorization everywhere. Absence of evidence is not authorization, and the
 * documented contract for a missing posting is the negative.
 */
describe("authorization where the job is located, nothing on file", () => {
  const ASKED =
    "Are you legally authorized to work in the country where the job is located?";

  it("answers no for a US-named posting with an empty profile", () => {
    const d = conservativeDefaultAnswer(ASKED, {
      location: "San Francisco, CA, United States",
      workCountries: [],
    });
    expect(d).not.toBeNull();
    expect(d!.answer).toMatch(/^No/);
    expect(resolveBooleanAnswer(d!.answer)).toBe("no");
  });

  it("answers no for a worldwide posting with an empty profile", () => {
    const d = conservativeDefaultAnswer(ASKED, {
      location: "Remote",
      remoteScope: "worldwide",
      workCountries: [],
    });
    expect(d!.answer).toMatch(/^No/);
    expect(resolveBooleanAnswer(d!.answer)).toBe("no");
  });

  it("answers no when no posting is passed at all", () => {
    const d = conservativeDefaultAnswer(ASKED);
    expect(d).not.toBeNull();
    expect(d!.answer).toMatch(/^No/);
    expect(resolveBooleanAnswer(d!.answer)).toBe("no");
  });
});
```

